SELECT count(*) totcnt FROM robot.member member WHERE 1 = 1
AND member.userid = #{userid}
AND member.nickname LIKE #{query}

SELECT R1.* FROM( SELECT member.userid, member.nickname, member.email, member.exp_robot, member.exp_castle, member.gold, member.gem, DATE_FORMAT(member.regdate, '%Y-%m-%d %H:%i:%s') regdate FROM robot.member member WHERE 1 = 1
AND member.userid = #{userid}
AND member.nickname LIKE #{query}
ORDER BY member.regdate DESC ) R1
LIMIT ${length} OFFSET ${start}
